def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v2 == 0:
        return None

    value = (v1 / v2) * 100

    return {
        "value": value,
        "trace": {
            "periodic_lease_payments": v1,
            "total_future_minimum_lease_payments": v2,
            "ratio": v1 / v2,
            "percentage": value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
